<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue'
import {ElMessage,ElMessageBox,type FormInstance} from 'element-plus'
import {api,post,type Stock,type Order,type User} from '../api'
const props=defineProps<{user:User}>()
const stocks=ref<Stock[]>([]),orders=ref<Order[]>([]),dialog=ref<'stock'|'order'|''>(''),saving=ref(false),formRef=ref<FormInstance>(),busy=ref<number|null>(null)
const stock=reactive({crop:'番茄',batch:'',grade:'A',quantity:1,source:''}),order=reactive({stock_id:0,customer:'',quantity:1,price:0})
async function load(){try{[stocks.value,orders.value]=await Promise.all([api<Stock[]>('/stocks'),api<Order[]>('/orders')])}catch(e){ElMessage.error((e as Error).message)}}
onMounted(load)
function open(kind:'stock'|'order'){Object.assign(stock,{crop:'番茄',batch:'',grade:'A',quantity:1,source:''});Object.assign(order,{stock_id:stocks.value[0]?.id||0,customer:'',quantity:1,price:0});dialog.value=kind}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{await post(dialog.value==='stock'?'/stocks':'/orders',dialog.value==='stock'?stock:order);ElMessage.success(dialog.value==='stock'?'批次已入库':'订单已创建，库存已预占');dialog.value='';load()}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
async function act(row:Order,action:'ship'|'cancel'){try{await ElMessageBox.confirm(action==='ship'?'确认实物已出库？完成后扣减库存。':'取消订单并释放预占库存？','订单确认');busy.value=row.id;await post(`/orders/${row.id}/${action}`,{});ElMessage.success('订单处理完成');load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}finally{busy.value=null}}
</script>
<template><div class="page-title"><div><h1>库存与销售订单</h1><p>入库 → 订单预占 → 实际出库，数量由数据库事务保证</p></div><div class="flex" v-if="user.role==='farmer'"><el-button @click="open('stock')">农产品入库</el-button><el-button type="primary" @click="open('order')">创建订单</el-button></div></div>
<section class="panel"><h2>农产品库存</h2><el-table :data="stocks"><el-table-column prop="batch" label="批次"/><el-table-column prop="crop" label="品类"/><el-table-column prop="source" label="种植来源" min-width="160"/><el-table-column prop="grade" label="等级"/><el-table-column prop="quantity" label="库存 kg"/><el-table-column prop="reserved" label="预占 kg"/><el-table-column prop="available" label="可用 kg"/><el-table-column label="数据来源"><template #default="{row}"><el-tag :type="row.demo?'warning':'success'">{{row.demo?'演示':'用户入库'}}</el-tag></template></el-table-column></el-table></section>
<section class="panel"><h2>销售订单</h2><el-table :data="orders" empty-text="暂无订单"><el-table-column label="订单号"><template #default="{row}">O-{{row.id}}</template></el-table-column><el-table-column prop="customer" label="客户"/><el-table-column prop="quantity" label="数量 kg"/><el-table-column prop="price" label="单价 元/kg"/><el-table-column prop="amount" label="金额 元"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="190" v-if="user.role==='farmer'"><template #default="{row}"><div class="flex" v-if="row.status==='待出库'"><el-button link type="primary" :disabled="busy===row.id" @click="act(row,'ship')">确认出库</el-button><el-button link type="danger" :disabled="busy===row.id" @click="act(row,'cancel')">取消订单</el-button></div><span v-else class="muted">已处理</span></template></el-table-column></el-table></section>
<el-dialog :model-value="!!dialog" @close="dialog=''" :title="dialog==='stock'?'农产品入库':'创建销售订单'" width="520px" destroy-on-close><el-form ref="formRef" :model="dialog==='stock'?stock:order" label-position="top"><template v-if="dialog==='stock'"><el-form-item label="品类" prop="crop" :rules="[{required:true,message:'填写品类'}]"><el-input v-model="stock.crop"/></el-form-item><el-form-item label="采收批次" prop="batch" :rules="[{required:true,message:'填写批次'}]"><el-input v-model="stock.batch" placeholder="例如 H-1001"/></el-form-item><el-form-item label="种植来源"><el-input v-model="stock.source" placeholder="例如 T-20260701"/></el-form-item><el-form-item label="等级"><el-select v-model="stock.grade"><el-option label="A" value="A"/><el-option label="B" value="B"/><el-option label="未分级" value="未分级"/></el-select></el-form-item><el-form-item label="数量（kg）"><el-input-number v-model="stock.quantity" :min="0.001" :precision="3"/></el-form-item></template><template v-else><el-form-item label="库存批次" prop="stock_id" :rules="[{required:true,message:'选择库存批次'}]"><el-select v-model="order.stock_id" style="width:100%"><el-option v-for="s in stocks" :key="s.id" :value="s.id" :label="`${s.crop} / ${s.batch} / 可用 ${s.available} kg`"/></el-select></el-form-item><el-form-item label="客户" prop="customer" :rules="[{required:true,message:'填写客户'}]"><el-input v-model="order.customer" placeholder="例如 社区生鲜店"/></el-form-item><el-form-item label="数量（kg）"><el-input-number v-model="order.quantity" :min="0.001" :precision="3"/></el-form-item><el-form-item label="单价（元/kg）"><el-input-number v-model="order.price" :min="0" :precision="2"/></el-form-item><div class="danger-note">提交后预占库存；确认出库后才扣减实际库存。</div></template></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认</el-button></template></el-dialog>
</template>
